// Launch Radar dashboard. Data comes from data.js (ROWS, NAMES, CATS,
// CHAINS, GROUPS, CELLS, META), all generated by main.ts from the snapshot.
// Row string format (comma-separated, money in $ thousands, base36):
// slug,tvl36,chg,age,launch36,exp36,verdict,chainIdx,catIdx,watch,nchains
// verdict: 0 Farm, 1 Thin, 2 Skip. chg/age empty when unknown.
// NAMES is a "boardIndex:Real Name" string for rows whose real name differs
// from the slug derivation; odds come from CELLS by (category group, TVL
// band); low/high band and farm costs are derived from expected value,
// the band error, the farm chain and the verdict (see the method section).
"use strict";
const $ = (id) => document.getElementById(id);
const ACR = new Set(["rwa","dao","amm","dex","nft","ai","lp","defi","cex","btc","eth","sol","sui","usd","usdt","usdc","yusd","adi","ao","tv","v2","v3","dapp","api","otc","p2p","cdp","lrt","lst","evm","zk","pos","pow","apr","apy"]);
function deriveName(slug) {
  return slug.split("-").map((w) => {
    const m = w.match(/^(\d+)(.*)$/);
    if (m && m[2]) return m[1] + m[2][0].toUpperCase() + m[2].slice(1);
    if (ACR.has(w)) return w.toUpperCase();
    if (w.length > 3 && w.endsWith("usd")) return w.toUpperCase();
    if (w.length <= 2) return w.toUpperCase();
    return w[0].toUpperCase() + w.slice(1);
  }).join(" ");
}
const VERDICTS = ["Farm", "Thin", "Skip"];
function parseRow(s, idx) {
  const f = s.split(",");
  return { idx, slug: f[0], tvlK: parseInt(f[1], 36), chg: f[2] === "" ? null : +f[2],
    age: f[3] === "" ? null : +f[3], launchK: parseInt(f[4], 36), expK: parseInt(f[5], 36),
    verdict: +f[6], chainIdx: +f[7], catIdx: +f[8], watch: f[9] === "1", nchains: +f[10] };
}
const ROWS_P = window.ROWS.map(parseRow);
const NAMES_BY_IDX = new Map(window.NAMES === "" ? [] : window.NAMES.split("|").map((e) => {
  const i = e.indexOf(":");
  return [+e.slice(0, i), e.slice(i + 1)];
}));
const bySlug = new Map(ROWS_P.map((r) => [r.slug, r]));
function nameOf(r) { return NAMES_BY_IDX.get(r.idx) || deriveName(r.slug); }
function catOf(r) { return window.CATS[r.catIdx]; }
function chainOf(r) { return window.CHAINS[r.chainIdx]; }
function gasOf(r) { return chainOf(r) === "Ethereum" ? 8 : 0.5; }
function costsOf(r) { const mid = 5 * gasOf(r); return { low: mid / 2, mid, high: mid * 2 }; }
function depositOf(r) {
  if (r.verdict === 2) return 0;
  const full = chainOf(r) === "Ethereum" ? 50 : 150;
  return r.verdict === 0 ? full : full / 2;
}
function groupOf(cat) { return window.GROUPS.includes(cat) ? cat : "Other"; }
function bandIdx(tvlK) { const t = tvlK * 1000; return t < 2e7 ? 0 : t < 1e8 ? 1 : t < 1e9 ? 2 : 3; }
function cellOf(r) {
  const g = window.GROUPS7.indexOf(groupOf(catOf(r)));
  return window.CELLS[g * 4 + bandIdx(r.tvlK)];
}
function oddsOf(r) { return cellOf(r)[2] / 1000; }
function fmt$(k) {
  const d = k * 1000;
  if (d >= 1e9) return "$" + (d / 1e9).toFixed(2) + "B";
  if (d >= 1e6) return "$" + (d / 1e6).toFixed(2) + "M";
  if (d >= 1e3) return "$" + (d / 1e3).toFixed(1) + "K";
  return "$" + Math.round(d);
}
function fmtM(v) { return Number.isInteger(v) ? String(v) : v.toFixed(2); }
function fmtGas(v) { return String(v); }
function fmtPct(x) { return (x * 100).toFixed(1) + "%"; }
function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;"); }

// The six farm-step templates — identical to lib/model.ts buildFarmSteps.
function buildSteps(r) {
  const name = nameOf(r), chain = chainOf(r), dep = depositOf(r), gas = gasOf(r);
  const c = costsOf(r), v = VERDICTS[r.verdict];
  const reason = v === "Farm" ? "farm it at the size above"
    : v === "Thin" ? "farm it, but at half the size above, or skip it if gas rises"
    : "the cost does not pay; re-check it next snapshot";
  const steps = [];
  steps.push("Use a fresh wallet that holds only the funds you plan to farm, and keep its seed phrase offline. Cost: under $3 of gas for the first transaction. Time: 5 minutes.");
  if (v === "Skip") {
    steps.push("Do not deposit into " + name + " for now: the expected gain does not cover the cost. Cost: $0. Time: 5 minutes to note it and move on.");
    steps.push("Re-check " + name + " next snapshot: if its TVL grows or a points program appears, farm it then. Cost: no fee to check. Time: 10 minutes.");
  } else {
    steps.push("Deposit $" + dep + " into " + name + "'s main product on " + chain + " and keep the position. Cost: $" + dep + " of capital and about $" + fmtGas(gas) + " of gas. Time: 15 minutes to set up.");
    steps.push("Make one qualifying action each week for 30 days, such as a deposit, a borrow, a swap or a vote. Cost: about $" + fmtGas(gas) + " of gas a week, 4 actions in all. Time: 10 minutes a week.");
  }
  if (v === "Skip") steps.push("Keep the wallet ready with $" + fmtGas(gas) + " of gas on " + chain + " so you can start within a day if it qualifies. Cost: $" + fmtGas(gas) + " of gas held ready. Time: 5 minutes.");
  else steps.push("Hold the position for at least 30 days so the activity is counted in more than one snapshot. Cost: the $" + dep + " stays in the position. Time: 30 days.");
  steps.push("Total farm cost is about $" + fmtM(c.low) + " at low gas, $" + fmtM(c.mid) + " at mid gas and $" + fmtM(c.high) + " at high gas, so the airdrop must be worth at least $" + fmtM(c.mid) + " to break even. Verdict: " + v.toUpperCase() + " — " + reason + ". Cost: $" + fmtM(c.mid) + " mid, $" + fmtM(c.low) + " to $" + fmtM(c.high) + " across gas levels. Time: 30 days in all.");
  steps.push("Before you withdraw, open the protocol's own points or rewards page and claim only from the link it publishes, then write the wallet, the dates and every transaction in a farm log. Cost: no fee to check, and never pay to claim. Time: 15 minutes.");
  return steps;
}

// ---- header, KPIs, model sections ------------------------------------------
const M = window.META;
$("modelLine").textContent = M.formula + "  ·  fitted on n=" + M.fittedN + " trading protocols.";
const kpis = [
  [M.total + "/" + M.total, "Protocols accounted"],
  [String(M.pre), "Board rows (pre-token)"],
  [M.watch + "/" + M.watch, "Watchlist covered"],
  [String(M.tradingRec) + " (" + M.fittedN + " fitted)", "Trading anchors"],
  [M.model, "Model"],
  [fmtPct(M.valid.cv5), "5-fold median error"],
  [fmtPct(M.valid.wMape), "Walk-forward median error"],
  [fmtPct(M.valid.hA) + " / " + fmtPct(M.valid.hB), "Held-out A / B median errors"],
];
$("kpis").innerHTML = kpis.map(([b, l]) => '<div class="kpi"><b>' + esc(b) + '</b><span>' + esc(l) + "</span></div>").join("");
const keptNames = M.terms.filter((t) => t[4]).map((t) => t[0]);
$("formula").textContent = "Chosen model: " + M.formula + ". " + (keptNames.length === 0
  ? "No extra term improved the 5-fold held-out median error by 2 points or more, so the chosen model is the base model alone."
  : "Kept terms: " + keptNames.join(", ") + ".");
$("fitNote").textContent = "Fitted on n=" + M.fittedN + " trading protocols with a positive market cap (of " + M.tradingRec + " that record a token; " + M.excluded + " excluded with zero or negative market cap, since log10 is undefined there). All fits use only the snapshot's own figures; no protocol name is hardcoded.";
const TERM_LABELS = { growth: "growth (change_7d)", age: "age (age_days)", quadratic: "quadratic (logTVL^2)", category: "category offsets" };
$("termsBody").innerHTML = M.terms.map((t) =>
  "<tr><td>" + esc(TERM_LABELS[t[0]] || t[0]) + "</td><td>" + t[1] + "</td><td>" + fmtPct(t[2]) + "</td><td>" + fmtPct(t[3]) + "</td><td>" + (t[4] ? "Kept" : "Rejected") + "</td></tr>").join("");
$("validBody").innerHTML = [
  ["5-fold cross-validation", fmtPct(M.valid.cv5), "fold = index in slug order mod 5, n=" + M.valid.cv5n],
  ["Held-out A (every 5th, from 0)", fmtPct(M.valid.hA), "test n=" + M.valid.hAn],
  ["Held-out B (every 5th, from 2)", fmtPct(M.valid.hB), "test n=" + M.valid.hBn],
  ["Walk-forward", fmtPct(M.valid.wMape), "fit on listed_at ≤ " + M.valid.wCut + " (n=" + M.valid.wOld + "), test on newer (n=" + M.valid.wNew + ")"],
].map((r) => "<tr><td>" + r[0] + "</td><td>" + r[1] + "</td><td>" + esc(r[2]) + "</td></tr>").join("");
$("calBody").innerHTML = M.cal.map((d, i) =>
  "<tr><td>" + (i + 1) + "</td><td>" + d[0] + "</td><td>" + fmt$(d[1]) + "</td><td>" + fmt$(d[2]) + "</td><td>" + d[3].toFixed(2) + "</td></tr>").join("");
$("oddsNote").textContent = "Overall share that record a token: " + M.tradingRec + "/" + M.total + " = " + (M.globalShare * 100).toFixed(1) + "%. Verdicts on this board: Farm " + M.vc[0] + ", Thin " + M.vc[1] + ", Skip " + M.vc[2] + ".";
$("footSrc").textContent = "Snapshot as of " + M.asOf + " · Source: " + M.source;

// ---- filters, sorting, board ----------------------------------------------
const fCat = $("fCat"), fChain = $("fChain");
fCat.innerHTML = '<option value="">All categories</option>' + window.CATS.map((c) => "<option>" + esc(c) + "</option>").join("");
fChain.innerHTML = '<option value="">All chains</option>' + window.CHAINS.map((c) => "<option>" + esc(c) + "</option>").join("");
let sortKey = "rank", sortDir = 1;
function sortVal(r, k) {
  switch (k) {
    case "rank": return ROWS_P.indexOf(r);
    case "name": return nameOf(r);
    case "cat": return catOf(r);
    case "chain": return chainOf(r);
    case "tvl": return r.tvlK;
    case "chg": return r.chg === null ? -1e9 : r.chg;
    case "age": return r.age === null ? -1 : r.age;
    case "launch": return r.launchK;
    case "odds": return oddsOf(r);
    case "exp": return r.expK;
    case "band": return r.expK;
    case "verdict": return r.verdict;
    case "cost": return costsOf(r).mid;
    default: return 0;
  }
}
function filtered() {
  const cat = fCat.value, ch = fChain.value, vd = $("fVerdict").value;
  const minT = parseFloat($("fMinTvl").value) || 0, w = $("fWatch").checked;
  const q = $("fText").value.trim().toLowerCase();
  let list = ROWS_P.filter((r) =>
    (!cat || catOf(r) === cat) && (!ch || chainOf(r) === ch) &&
    (vd === "" || VERDICTS[r.verdict] === vd) &&
    (r.tvlK * 1000 >= minT) && (!w || r.watch) &&
    (!q || nameOf(r).toLowerCase().includes(q) || r.slug.includes(q)));
  list = [...list].sort((a, b) => {
    const va = sortVal(a, sortKey), vb = sortVal(b, sortKey);
    const c = va < vb ? -1 : va > vb ? 1 : 0;
    return c * sortDir || (ROWS_P.indexOf(a) - ROWS_P.indexOf(b));
  });
  return list;
}
function renderBoard() {
  const list = filtered();
  $("rowCount").textContent = "— " + list.length + " of " + ROWS_P.length + " rows";
  $("tbody").innerHTML = list.map((r) => {
    const c = costsOf(r), v = VERDICTS[r.verdict];
    const band = fmt$(Math.round(r.expK * (1 - M.e))) + " – " + fmt$(Math.round(r.expK * (1 + M.e)));
    return '<tr data-slug="' + esc(r.slug) + '"><td>' + (ROWS_P.indexOf(r) + 1) + "</td><td><b>" + esc(nameOf(r)) + "</b>" + (r.watch ? " ★" : "") + "</td><td>" + esc(catOf(r) || "—") + "</td><td>" + esc(chainOf(r)) + "</td><td class=\"num\">" + fmt$(r.tvlK) + "</td><td class=\"num\">" + (r.chg === null ? "—" : (r.chg > 0 ? "+" : "") + r.chg.toFixed(1) + "%") + "</td><td class=\"num\">" + (r.age === null ? "—" : r.age + "d") + "</td><td class=\"num\">" + fmt$(r.launchK) + "</td><td class=\"num\">" + oddsOf(r).toFixed(2) + "</td><td class=\"num\"><b>" + fmt$(r.expK) + "</b></td><td class=\"num\">" + band + "</td><td><span class=\"verdict v-" + v + "\">" + v + "</span></td><td class=\"num\">$" + fmtM(c.mid) + "</td></tr>";
  }).join("");
}
document.querySelectorAll("#board thead th").forEach((th) => {
  th.addEventListener("click", () => {
    const k = th.dataset.k;
    if (sortKey === k) sortDir = -sortDir; else { sortKey = k; sortDir = k === "name" || k === "cat" || k === "chain" ? 1 : -1; }
    renderBoard();
  });
});
["fCat", "fChain", "fVerdict", "fMinTvl", "fWatch", "fText"].forEach((id) =>
  $(id).addEventListener("input", renderBoard));
$("tbody").addEventListener("click", (ev) => {
  const tr = ev.target.closest("tr");
  if (tr) location.hash = "#detail=" + tr.dataset.slug;
});

// ---- detail view ------------------------------------------------------------
function renderDetail(slug) {
  const r = bySlug.get(slug);
  const wrap = $("detailWrap"), board = $("boardWrap");
  if (!r) { wrap.hidden = true; board.hidden = false; return; }
  const c = costsOf(r), v = VERDICTS[r.verdict], cell = cellOf(r);
  const g = groupOf(catOf(r));
  const bandNames = ["$5M–$20M", "$20M–$100M", "$100M–$1B", "$1B+"];
  const band = fmt$(Math.round(r.expK * (1 - M.e))) + " – " + fmt$(Math.round(r.expK * (1 + M.e)));
  const fb = cell[3] === 1 ? " (cell n &lt; 5 — odds fall back to the category level)" : cell[3] === 2 ? " (odds fall back to the overall share)" : "";
  const cells = [
    ["Rank", "#" + (ROWS_P.indexOf(r) + 1) + " of " + ROWS_P.length],
    ["TVL", fmt$(r.tvlK)], ["7d change", r.chg === null ? "—" : (r.chg > 0 ? "+" : "") + r.chg.toFixed(1) + "%"],
    ["Age", r.age === null ? "—" : r.age + " days since first listed"],
    ["Launch value", fmt$(r.launchK)], ["Odds", oddsOf(r).toFixed(3)],
    ["Expected value", fmt$(r.expK)], ["Band", band],
    ["Verdict", v], ["Farm cost (mid)", "$" + fmtM(c.mid)],
    ["Breakeven", "$" + fmtM(c.mid)], ["Deposit", "$" + depositOf(r)],
  ];
  $("detail").innerHTML =
    "<h3>" + esc(nameOf(r)) + (r.watch ? " ★ watchlist" : "") + "</h3>" +
    "<p>" + esc(catOf(r) || "No category") + " · farm chain " + esc(chainOf(r)) + " (cheapest of " + r.nchains + " listed) · slug " + esc(r.slug) + "</p>" +
    '<div class="dgrid">' + cells.map(([l, b]) => '<div class="dcell"><b>' + esc(b) + "</b><span>" + esc(l) + "</span></div>").join("") + "</div>" +
    "<p><b>Odds cell:</b> " + esc(g) + " · " + bandNames[bandIdx(r.tvlK)] + " — " + cell[0] + " peers, raw share " + (cell[1] / cell[0]).toFixed(3) + ", shrunk odds " + oddsOf(r).toFixed(3) + fb + ". " +
    "Odds describe the peers&rsquo; record; they do not predict whether or when a token is issued.</p>" +
    "<p><b>Model:</b> " + esc(M.formula) + " — launch value " + fmt$(r.launchK) + " &times; odds " + oddsOf(r).toFixed(3) + " = expected value " + fmt$(r.expK) + ".</p>" +
    "<h3>How to farm it</h3><ol class=\"steps\">" + buildSteps(r).map((s) => "<li>" + esc(s) + "</li>").join("") + "</ol>";
  wrap.hidden = false;
  board.hidden = true;
}
function applyHash() {
  const h = location.hash;
  if (h.startsWith("#detail=")) { renderDetail(decodeURIComponent(h.slice(8))); return; }
  $("detailWrap").hidden = true;
  $("boardWrap").hidden = false;
  if (h === "#filter=watchlist") { $("fWatch").checked = true; }
  renderBoard();
}
window.addEventListener("hashchange", applyHash);
applyHash();
